"""Independent prospective-study notebook, without provisional accuracy claims."""
CSS=r"""
.sig-intro{max-width:900px;margin:34px 0}.sig-intro h1{font:44px Georgia,serif;letter-spacing:-1px}.sig-badge{display:inline-block;padding:8px 12px;border:1px solid #c7d3c6;color:#245a49;background:#eef3e9;font-size:12px}.sig-layout{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(260px,1fr);gap:24px;margin:24px 0}.sig-panel{min-width:0;padding:26px;border:1px solid var(--line);background:#fffefb;border-radius:6px}.sig-panel h2{font:28px Georgia,serif;margin:8px 0 20px}.sig-panel select{max-width:100%;width:100%;font:inherit;padding:12px;background:#fffdf7;border:1px solid #c7c2b5;margin:8px 0 16px}.sig-panel small,.sig-small{font-size:12px;color:var(--muted);line-height:1.7}.sig-facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin:22px 0}.sig-facts strong{display:block;font:27px Georgia,serif;margin:7px 0}.sig-controls{display:flex;gap:8px;flex-wrap:wrap}.sig-controls button,.sig-action{padding:10px 14px;background:#fffdf7;border:1px solid #c7c2b5;font:inherit;color:var(--ink);cursor:pointer}.sig-controls button[aria-pressed=true]{border-color:var(--blue);color:var(--blue);background:#edf1fd}.sig-trace{padding:20px 0;border-top:1px solid var(--line)}.sig-pin{background:#fff7de;padding:18px;margin:16px 0;overflow-wrap:anywhere}.sig-panel pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:10px}.sig-svg{display:block;width:100%;height:auto}.sig-source{padding:15px 0;border-top:1px solid var(--line)}.sig-table{overflow:auto;max-width:100%}.sig-table table{border-collapse:collapse;min-width:600px;width:100%;font-size:12px}.sig-table td,.sig-table th{text-align:left;padding:12px;white-space:nowrap;border-bottom:1px solid var(--line)}@media(max-width:760px){.sig-layout{grid-template-columns:1fr}.sig-intro h1{font-size:34px}.sig-panel{padding:18px}.sig-facts{grid-template-columns:1fr;gap:0}.sig-facts div{border-top:1px solid var(--line);padding:12px 0}}
"""
JS=r"""
let SG=null,SGError=null,SGCommit=null,SGMemory=null;
const GS={tab:'commitments',series:'',forecaster:'last_value_empirical',point:0,pins:[],seq:0};
function sigTarget(){return SG?.cohort.find(s=>s.id===GS.series)||SG?.cohort[0]}
function sigLabel(t){return t.contract.gpu.toUpperCase()+' · '+t.contract.provider+' · '+(t.contract.min_gpus===null?'node size unreported':t.contract.min_gpus+' GPU node')}
function sigRows(){return (SGCommit?.rows||[]).filter(r=>r.series_id===sigTarget()?.id&&r.forecaster===GS.forecaster).sort((a,b)=>a.horizon_days-b.horizon_days)}
function sigPlot(){
 const host=$('#sig-plot'),rows=sigRows();if(!host||!rows.length)return;
 const w=Math.max(250,host.clientWidth),h=250,L=55,R=20,T=30,B=42,max=Math.max(...rows.map(r=>r.q90))*1.2,x=n=>L+n/7*(w-L-R),y=v=>T+(1-v/max)*(h-T-B);
 const chosen=rows[Math.min(GS.point,rows.length-1)];let body=[0,.5,1].map(f=>'<line x1="'+L+'" x2="'+(w-R)+'" y1="'+y(max*f)+'" y2="'+y(max*f)+'" stroke="#e2e5dc"/><text x="'+(L-9)+'" y="'+(y(max*f)+4)+'" text-anchor="end" font-size="11" fill="#5e6f73">'+money(max*f)+'</text>').join('');
 body+='<polyline points="'+rows.map(r=>x(r.horizon_days)+','+y(r.q50)).join(' ')+'" fill="none" stroke="#355cdb" stroke-dasharray="5 4" stroke-width="2"/>'+rows.map(r=>'<circle cx="'+x(r.horizon_days)+'" cy="'+y(r.q50)+'" r="5" fill="#355cdb"/><text x="'+x(r.horizon_days)+'" y="'+(h-13)+'" text-anchor="middle" font-size="11" fill="#5e6f73">'+r.horizon_days+'d</text>').join('');
 body+='<circle cx="'+x(chosen.horizon_days)+'" cy="'+y(chosen.q50)+'" r="8" fill="none" stroke="#355cdb"/>';
 host.innerHTML='<svg class="sig-svg" role="img" aria-label="Actual committed cold-start reference quantiles, not signal-model improvement" viewBox="0 0 '+w+' '+h+'">'+body+'</svg>';
 $('#sig-point').innerHTML='<span class="value-hand">Committed before the outcome.</span><p>'+esc(chosen.target_date)+' · '+chosen.horizon_days+' days · USD / GPU-hour</p><strong data-sig-q50="'+chosen.q50+'" style="font:28px Georgia,serif">'+money(chosen.q50)+'</strong><p class="sig-small">q10 '+money(chosen.q10)+' · q90 '+money(chosen.q90)+'. Initial references collapse to zero-width intervals because only one retained day exists; these are uncalibrated.</p>'
}
function sigPins(){return GS.pins.map(p=>'<article class="sig-pin"><span class="value-hand">An immutable commitment note.</span><p>'+esc(p.label)+'</p><details id="sig-pin-'+p.id+'"><summary>Exact values and provenance</summary><pre>'+esc(JSON.stringify(p,null,2))+'</pre></details></article>').join('')}
function sigCommitments(){
 const t=sigTarget(),rows=sigRows(),latest=SG.latest_snapshot?.prices.rows.find(r=>r.id===t?.id);
 return '<div class="sig-layout"><section class="sig-panel"><div class="eyebrow">FIRST REAL FORECAST COMMITMENT / OUTCOMES PENDING</div><h2>Four contracts. Future answers.</h2><label for="sig-series">Exact provider configuration</label><select id="sig-series">'+SG.cohort.map(t=>'<option value="'+esc(t.id)+'" '+(sigTarget().id===t.id?'selected':'')+'>'+esc(sigLabel(t))+'</option>').join('')+'</select><label for="sig-forecaster">Official starter reference</label><select id="sig-forecaster">'+SG.protocol.references.map(x=>'<option '+(GS.forecaster===x?'selected':'')+'>'+x+'</option>').join('')+'</select>'+(rows.length?'<div id="sig-plot"></div><div class="sig-controls" aria-label="Committed horizon">'+rows.map((r,i)=>'<button data-sig-point="'+i+'" aria-pressed="'+(GS.point===i)+'">'+r.horizon_days+' days</button>').join('')+'</div><div id="sig-point" class="value-inspector" aria-live="polite"></div><button id="sig-pin" class="sig-action">＋ Pin exact forecast</button>':'<p class="sig-small">Opening the actual commitment. No placeholder predictions are drawn.</p>')+'<p class="sig-small">This cold-start pilot is excluded from the signal-value comparison. Connecting the three submitted points does not create daily predictions.</p><details id="sig-contract"><summary>Contract identity and source vintage</summary><pre>'+esc(JSON.stringify({contract:t,quote:latest,issued_at:SGCommit?.issued_at,information_cutoff:SGCommit?.information_cutoff,protocol_sha256:SG.protocol_sha256},null,2))+'</pre></details></section><aside class="sig-panel"><div class="eyebrow">COLLECTION READINESS</div><h2>Fresh quotes. Honest gates.</h2><div class="sig-facts"><div>Retained price days<strong>'+SG.readiness.retained_price_days+' / 56</strong></div><div>Matured pairs required<strong>32</strong></div><div>BLS periods observed<strong>'+SG.readiness.bls_periods_first_observed+' / 3</strong></div></div><p>Primary forecasts require actual chronological training and calibration data. New weight training is gated.</p><p class="sig-small">Latest observation: '+esc(SG.latest_snapshot?.prices.date||'missing')+'. Prices are advertised offers; region or node size can remain unreported. Fresh collection does not establish rentable capacity.</p><div class="value-hand">Let the data arrive.</div><p class="sig-small">Targets resolve on their actual observation dates. Scoring unlocks after each UTC day ends and requires matching retained truth.</p><p class="sig-small">26 registered weekly origins, November 22, 2026–May 16, 2027. Scheduled external work ends May 25.</p></aside></div>'+sigPins()
}

function sigResearchPlot(analysis){
 const points=analysis?.trajectory||[];if(!points.length)return '';
 const W=900,H=230,L=60,R=25,T=25,B=45,values=points.map(p=>p.comparisons[0].difference),cap=Math.max(...values.map(Math.abs),.00000001),x=i=>L+(i+.5)/points.length*(W-L-R),y=v=>T+(cap-v)/(2*cap)*(H-T-B);
 const bars=values.map((v,i)=>'<g id="sig-bar-'+esc(points[i].origin)+'" tabindex="0" role="button" data-sig-origin="'+esc(points[i].origin)+'" aria-label="'+esc(points[i].origin)+' all signals minus price-only loss '+v+'"><rect x="'+(x(i)-Math.min(20,(W-L-R)/points.length/3))+'" y="'+Math.min(y(0),y(v))+'" width="'+Math.min(40,(W-L-R)/points.length*2/3)+'" height="'+Math.max(1,Math.abs(y(v)-y(0)))+'" fill="'+(v<=0?'#39725d':'#b17722')+'"/><text x="'+x(i)+'" y="'+(H-15)+'" text-anchor="middle" font-size="10" fill="#52666a">'+shortDate(points[i].origin)+'</text></g>').join('');
 let total=0,n=0;const cumulative=points.map(p=>{total+=p.comparisons[0].difference*p.matched_cells;n+=p.matched_cells;return total/n}),max=Math.max(...cumulative.map(Math.abs),.00000001),cy=v=>T+(max-v)/(2*max)*(H-T-B);
 const line=cumulative.map((v,i)=>x(i)+','+cy(v)).join(' ');
 const widths=points.map(p=>p.comparisons[0].mean_interval_width),maxWidth=Math.max(...widths,.00000001)*1.15,wx=v=>L+v/maxWidth*(W-L-R),wy=v=>T+(1-v)*(H-T-B);
 const circles=points.map((p,i)=>{const c=p.comparisons[0],coverage=c.coverage_numerator/c.coverage_denominator;return '<circle id="sig-coverage-'+esc(p.origin)+'" tabindex="0" role="button" data-sig-origin="'+esc(p.origin)+'" aria-label="'+esc(p.origin)+' coverage '+c.coverage_numerator+' of '+c.coverage_denominator+', width '+c.mean_interval_width+'" cx="'+wx(widths[i])+'" cy="'+wy(coverage)+'" r="5" fill="#355cdb"/>'}).join('');
 const chosen=points.find(p=>p.origin===GS.origin)||points.at(-1);
 return (analysis.classification==='synthetic_contract_fixture'?'<p>Synthetic UI contract fixture; no market result.</p>':'')+'<h3>Where did the difference arise?</h3><p class="sig-small">All signals minus price-only pinball. Negative is better; every eligible origin is retained.</p><svg class="sig-svg" role="group" aria-label="Actual paired loss differences by origin" viewBox="0 0 '+W+' '+H+'"><line x1="'+L+'" x2="'+(W-R)+'" y1="'+y(0)+'" y2="'+y(0)+'" stroke="#81918a"/><text x="6" y="18" font-size="11">+'+fmt(cap,6)+'</text><text x="6" y="'+(H-B)+'" font-size="11">−'+fmt(cap,6)+'</text>'+bars+'</svg><h3>Cumulative difference</h3><p class="sig-small">Cell-weighted accumulation of the same retained observations; this curve can rise or fall.</p><svg class="sig-svg" role="img" aria-label="Actual cumulative matched loss difference" viewBox="0 0 '+W+' '+H+'"><line x1="'+L+'" x2="'+(W-R)+'" y1="'+cy(0)+'" y2="'+cy(0)+'" stroke="#81918a"/><polyline points="'+line+'" fill="none" stroke="#355cdb" stroke-width="2"/></svg><h3>Coverage needs its width</h3><p class="sig-small">Each point is one origin: all-signals interval width versus observed coverage. Dashed line is nominal80%; small correlated cohorts do not establish population calibration.</p><svg class="sig-svg" role="group" aria-label="Actual coverage versus interval width" viewBox="0 0 '+W+' '+H+'"><line x1="'+L+'" x2="'+(W-R)+'" y1="'+wy(.8)+'" y2="'+wy(.8)+'" stroke="#81918a" stroke-dasharray="4 4"/><text x="8" y="'+wy(.8)+'" font-size="11">80%</text><text x="'+L+'" y="'+(H-12)+'" font-size="11">Interval width →</text>'+circles+'</svg><details id="sig-selected-origin"><summary>Selected origin '+esc(chosen.origin)+' · '+chosen.matched_cells+' matched cells</summary><pre>'+esc(JSON.stringify(chosen,null,2))+'</pre></details>'
}

function sigLearning(){
 const analysis=SG.analysis,points=analysis?.trajectory||[];
 return '<section class="sig-panel"><div class="eyebrow">REGISTERED PRIMARY TEST / SEVEN-DAY PINBALL</div><h2>Do the signals earn their place?</h2><p>All eight feature combinations share the same learner, fit/calibration labels and tuning budget. The primary comparison is all signals versus price-only; drift is a separate competitiveness reference.</p><div class="sig-table" tabindex="0" role="region" aria-label="Registered feature ablations"><table><thead><tr><th>Arm</th><th>News</th><th>Infrastructure</th><th>BLS</th><th>Status</th></tr></thead><tbody>'+SG.protocol.learner.feature_masks.map(m=>'<tr><td>'+m+(m==='000'?' · incumbent':m==='111'?' · challenger':'')+'</td>'+[...m].map(v=>'<td>'+(v==='1'?'included':'excluded')+'</td>').join('')+'<td>'+(SG.primary_scored_cells>0?'Paired outcome records available':SG.ledger.some(x=>x.status==='issued_primary')?'Issued; outcomes pending':'Pending sufficient retained history')+'</td></tr>').join('')+'</tbody></table></div>'+(points.length?sigResearchPlot(analysis)+'<div class="sig-table"><table><thead><tr><th>Origin</th><th>Matched cells</th><th>All signals − price-only loss</th></tr></thead><tbody>'+points.map(p=>'<tr><td>'+p.origin+'</td><td>'+p.matched_cells+'</td><td>'+fmt(p.comparisons[0].difference,8)+'</td></tr>').join('')+'</tbody></table></div>':'<div class="empty"><h3>No eligible primary outcomes yet.</h3><p>No learning curve or improvement percentage is drawn before real paired scores exist.</p></div>')+'<p class="sig-small">Interim outcomes are descriptive. Final analysis waits for the registered panel to mature; uncertainty uses origin blocks only after at least 16 eligible origins. Individual-group claims also require sufficient signal variation and multiplicity control.</p></section><section class="sig-panel" style="margin-top:24px"><h2>The iteration ledger</h2>'+SG.ledger.map(r=>'<article class="sig-trace"><div class="eyebrow">'+esc(r.origin_date)+' · '+esc(r.kind.replaceAll('_',' '))+'</div><p>'+esc(r.hypothesis)+'</p><p><strong>'+r.rows+' committed rows</strong> · '+esc(r.score_status)+' outcomes</p><p class="sig-small">'+esc(r.criticism)+'</p><p class="sig-small">Decision: '+esc(r.decision.replaceAll('_',' '))+'</p>'+link(r.artifact,'Inspect the immutable commitment')+'</article>').join('')+'</section>'
}
function sigEvidence(){
 const s=SG.latest_snapshot;
 return '<div class="sig-layout"><section class="sig-panel"><div class="eyebrow">POINT-IN-TIME EVIDENCE</div><h2>What was actually known?</h2><p class="sig-small">First-observed timestamps determine availability. Publication dates alone never backdate a page into a historical forecast.</p><div class="sig-source"><strong>BLS electricity-distribution PPI</strong><p>Period '+esc(s?.bls?.latest_period||'unavailable')+' · index '+esc(s?.features.electricity_ppi_index??'missing')+'</p><p class="sig-small">This is an index, not a USD/kWh tariff. Preliminary values can be revised. The response vintage is frozen at retrieval.</p></div>'+(s?.events||[]).map(e=>'<article class="sig-source"><p>'+link(e.url,e.title)+'</p><p class="sig-small">'+esc(e.kind.replaceAll('_',' '))+' · '+(e.publication_verified?'Primary publication timestamp verified':'Publication unverified; excluded from predictive counts')+'<br>First observed '+esc(e.first_observed_at)+'</p></article>').join('')+'<details id="sig-features"><summary>Exact features, hashes and missingness</summary><pre>'+esc(JSON.stringify({features:s?.features,receipts:s?.receipts,errors:s?.errors},null,2))+'</pre></details></section><section class="sig-panel"><div class="eyebrow">PAST.DEV / ACTUAL RESEARCH TASKS</div><h2>Evidence crosses roles.</h2>'+(SGMemory?'<div class="sig-badge" data-sig-memory="'+SGMemory.eligibility.requirements_met+'">'+SGMemory.eligibility.writers+' writers · '+SGMemory.eligibility.readers+' readers · '+SGMemory.eligibility.cross_role_uses+' verified cross-role uses</div>'+SGMemory.steps.map(x=>'<article class="sig-trace"><strong>'+esc(x.role)+'</strong><p>'+esc(x.summary)+'</p><details id="sig-memory-'+esc(x.record_id)+'"><summary>Executed check and record</summary><pre>'+esc(JSON.stringify(x,null,2))+'</pre></details></article>').join('')+'<p class="sig-small">Next check changed after criticism: '+SGMemory.changed_after_criticism+'. Four actual Tinker planning decisions; zero new optimizer updates. This is not a forecast-accuracy result.</p>':'<p>Memory receipts are pending publication. No successful recall is assumed.</p>')+'<button id="sig-refresh-memory" class="sig-action">Refresh memory receipts</button></section></div>'
}
function signalsPage(){
 return '<div class="sig-intro"><div class="eyebrow">A SEPARATE PROSPECTIVE STUDY</div><h1>Evidence today.<br>Answers from the future.</h1><p>Testing whether news, infrastructure and economic signals improve GPU rental forecasts.</p><span class="sig-badge">'+esc(SG?.claim||'Opening the registered experiment…')+'</span></div><div class="sig-controls">'+[['commitments','Forecast commitments'],['learning','Learning + decisions'],['evidence','Signals + memory']].map(([k,t])=>'<button data-sig-tab="'+k+'" aria-pressed="'+(GS.tab===k)+'">'+t+'</button>').join('')+'</div>'+(!SG?'<div class="empty"><h2>'+(SGError?'The signals study could not load.':'Opening retained study artifacts…')+'</h2><p>The existing pricing views remain available.</p><button id="sig-retry" class="sig-action">Retry signals</button></div>':GS.tab==='commitments'?sigCommitments():GS.tab==='learning'?sigLearning():sigEvidence())+'<p class="sig-small"><a href="https://github.com/howdymary/compute-forecasting/blob/compute-observatory/docs/prospective-signals-v6.md">Registered methods, sources and limits ↗</a> · <a href="/api/signals-v6">Exact public study index</a></p>'
}
function bindSignals(){
 document.querySelectorAll('[data-sig-tab]').forEach(e=>e.onclick=()=>{GS.tab=e.dataset.sigTab;render()});
 if($('#sig-retry'))$('#sig-retry').onclick=loadSignals;
 if($('#sig-series'))$('#sig-series').onchange=e=>{GS.series=e.target.value;GS.point=0;render()};
 if($('#sig-forecaster'))$('#sig-forecaster').onchange=e=>{GS.forecaster=e.target.value;GS.point=0;render()};
 document.querySelectorAll('[data-sig-point]').forEach(e=>e.onclick=()=>{GS.point=+e.dataset.sigPoint;document.querySelectorAll('[data-sig-point]').forEach(b=>b.setAttribute('aria-pressed',b===e));sigPlot()});
 if($('#sig-pin'))$('#sig-pin').onclick=()=>{const row=sigRows()[GS.point];GS.pins.push({id:++GS.seq,label:sigLabel(sigTarget()),forecast:JSON.parse(JSON.stringify(row)),commitment_sha256:SG.ledger[0]?.id,protocol_sha256:SG.protocol_sha256});if(GS.pins.length>3)GS.pins.shift();render()};
 if($('#sig-refresh-memory'))$('#sig-refresh-memory').onclick=loadSignalsMemory;
 document.querySelectorAll('[data-sig-origin]').forEach(e=>{e.onclick=()=>{GS.origin=e.dataset.sigOrigin;render()};e.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();GS.origin=e.dataset.sigOrigin;render()}}});
 if($('#sig-plot'))sigPlot()
}
const sigPrevRender=render,sigPrevDownloads=downloads;
render=function(){sigPrevRender();if(view==='signals')bindSignals()};
downloads=function(){return sigPrevDownloads()+'<section class="research-figure"><h3>Prospective signals v6</h3><p><a href="/api/signals-v6">Registration, snapshots, commitments and pending outcomes</a> · <a href="/api/signals-v6/memory">Cross-role memory proof</a></p></section>'};
async function loadSignals(){
 SGError=null;try{const v=await fetchJson('/api/signals-v6');if(v.schema_version!==6)throw Error('Signals schema');SG=v;if(P&&view==='signals')render();if(v.ledger.length){SGCommit=await fetchJson(v.ledger[0].artifact);if(SGCommit.registration_sha256!==v.protocol_sha256)throw Error('Commitment protocol mismatch')}}catch(e){SGError=e}if(P&&view==='signals')render()
}
async function loadSignalsMemory(){try{const v=await fetchJson('/api/signals-v6/memory');if(v.schema_version===6&&v.eligibility)SGMemory=v}catch(e){}if(P&&view==='signals'&&GS.tab==='evidence')render()}
window.addEventListener('resize',()=>{if(view==='signals'&&GS.tab==='commitments')sigPlot()});
loadSignals();loadSignalsMemory();
"""
def enhance(html):
    replacements=[
        ('<button data-view="research">Research</button>','<button data-view="signals">Signals</button><button data-view="research">Research</button>'),
        ("({explore,value:valuePage,research,methods,downloads})","({explore,value:valuePage,signals:signalsPage,research,methods,downloads})"),
        ("['explore','value','research','methods','downloads'].includes(requested)","['explore','value','signals','research','methods','downloads'].includes(requested)")
    ]
    for old,new in replacements:
        if html.count(old)!=1:raise ValueError("Signal view insertion marker changed: "+old)
        html=html.replace(old,new)
    return html.replace("</style>",CSS+"</style>").replace("</script>",JS+"</script>")
